new file mode 100644
index 0000000..f768c9f
--- /dev/null
+++ b/src/Search/ProjectedShuffleCache.cs
@@ -0,0 +1,64 @@
+using CombatSolver.Engine.Common;
+using MegaCrit.Sts2.Core.Extensions;
+
+namespace CombatSolver;
+
+// One owner per search lane. Only RNG values and swap indexes survive a projection;
+// cards are sorted and evaluated afresh, including duplicate comparison keys.
+internal sealed class ProjectedShuffleCache
+{
+    private const int SlotCount = 16;
+    internal const int MaximumCardCount = 4096;
+    private sealed record Entry(PredictionRngState Rng, int[] Swaps);
+    private readonly Entry?[] _entries = new Entry[SlotCount];
+    public long Hits { get; private set; }
+    public long Misses { get; private set; }
+    public long Bypasses { get; private set; }
+
+    public void Shuffle(List<PredictedCard> cards, PredictionRngState state)
+    {
+        cards.Sort();
+        int count = cards.Count;
+        if (count < 2 || count > MaximumCardCount)
+        {
+            Bypasses++;
+            if (count > 1) cards.UnstableShuffle(state.ToRng());
+            return;
+        }
+
+        // Collisions only replace a bounded slot; equality checks every RNG word.
+        int slot = (count ^ (int)state.State0) & (SlotCount - 1);
+        Entry? entry = _entries[slot];
+        if (entry == null || entry.Swaps.Length != count - 1 || entry.Rng != state)
+        {
+            Misses++;
+            var rng = state.ToRng();
+            int[] swaps = new int[count - 1];
+            // The native UnstableShuffle visits n-1 through 1 in this order.
+            for (int index = count - 1; index > 0; index--)
+                swaps[index - 1] = rng.NextInt(index + 1);
+            entry = new Entry(state, swaps);
+            _entries[slot] = entry;
+        }
+        else
+        {
+            Hits++;
+        }
+        for (int index = count - 1; index > 0; index--)
+        {
+            int other = entry.Swaps[index - 1];
+            (cards[index], cards[other]) = (cards[other], cards[index]);
+        }
+    }
+
+    public void Clear() => Array.Clear(_entries);
+
+    // Drain counters at the existing worker handoff; retain the lane's cache entries.
+    public void DrainStatisticsFrom(ProjectedShuffleCache source)
+    {
+        Hits += source.Hits;
+        Misses += source.Misses;
+        Bypasses += source.Bypasses;
+        source.Hits = source.Misses = source.Bypasses = 0;
+    }
+}

